import{_ as t,a as o,b as a,c as n}from"./chunks/893fda8bb771e8b7e819.DQcukAyh.js";import{_ as r,o as i,c as s,a5 as l}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"How To Get What You Want Out Of Life","description":"","frontmatter":{"title":"How To Get What You Want Out Of Life","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/how-to-get-what-you-want-out-of-life.md","filePath":"en/letters/how-to-get-what-you-want-out-of-life.md"}'),p={name:"en/letters/how-to-get-what-you-want-out-of-life.md"};function h(u,e,d,c,f,g){return i(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="how-to-get-what-you-want-out-of-life" tabindex="-1">How To Get What You Want Out Of Life <a class="header-anchor" href="#how-to-get-what-you-want-out-of-life" aria-label="Permalink to &quot;How To Get What You Want Out Of Life&quot;">​</a></h1><p>Dan Koe · 2022-08-28 · <a href="https://thedankoe.com/letters/how-to-get-what-you-want-out-of-life/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/how-to-get-what-you-want-out-of-life">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/gCYfNTagJf8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>The modern education system is great at one thing:</p><p><em>Training people into replaceable jobs.</em></p><p>This was a realization I had before I went to college. I knew that even if I went, finding the right career for me wasn’t over when graduation came around.</p><p>I had 2 options if I wanted to make more than enough money to eliminate the problems that come from money:</p><p>Option 1:</p><ul><li>Climb the corporate ladder</li><li>Use my skills to build someone elses business</li><li>Sacrifice my wants and time for a higher paycheck</li></ul><p>Option 2:</p><ul><li>Create my own ladder</li><li>Use my skills to build my own business</li><li>Sacrifice my free time for leverage toward my goals</li></ul><p>I’m being dramatic here, of course.</p><p>I’ve been self-employed for 3-4 years now and I am <em>extremely</em> out of touch with most things. I have a distorted perception of corporate work and am well aware of that.</p><p>From what I’ve seen, there are few lines of work that have a shred of the benefits that self-employment do.</p><p>Ample rest, pursuing an intrinsic hierarchy of goals, not sitting in front of artificial blue light for 8 hours, the pursuit of mastery and the deep sense of satisfaction that comes with it… the list goes on.</p><p>The human psyche, general health, and the <em>basic need</em> for self-actualization are pushed under the rug for the sake of making a predictable amount of money.</p><p>This doesn’t make sense when good dopamine comes from hunting for your own survival, pursuing the goals <em>you</em> set, and achieving mastery in the skills <em>you</em> choose — not someone that offers to hold your hand toward their goals.</p><p>How do you prevent or escape this reality?</p><p>Skill acquisition, building a creative income source, and adopting the value of self-sufficiency.</p><p>But there’s more.</p><p><em>The internet has leveled the playing field.</em></p><p>People of all experience levels are solving their own problems, learning new skills, and posting their findings online in an engaging way.</p><p>This kills 4 birds with one stone.</p><ul><li>Learning leverage building skills through experience (like writing, persuasion, and other marketable skills that come with building a brand)</li><li>Building digital leverage (a following, network, and digital real estate that lives online forever)</li><li>Studying the interests they truly want to pursue (and learning about them by organizing their ideas and posting online)</li><li>Offering help to those 1-2 steps behind them (because people are losing trust in the “system” and want to learn from a human)</li></ul><p>The state of modern education has been changing right before our eyes.</p><p>Like Bitcoin, education will continue to decentralize.</p><p>Creators are the new teachers.</p><p>Consumers are the new students.</p><h2 id="the-new-education-system" tabindex="-1">The New Education System <a class="header-anchor" href="#the-new-education-system" aria-label="Permalink to &quot;The New Education System&quot;">​</a></h2><blockquote><p>The current education system will not prepare you for the future of work.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1546816648199507969?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">July 12, 2022</a></p></blockquote><p>In reality, what I’m going to teach you is the old education system.</p><p>Long before government-supported schools came into play, how did we learn?</p><p>From our parents, community, and experiences.</p><p>We touched fire, cried for a few minutes, and learned that life implies risk. Some controllable, some the product of self-deception and illusion.</p><p>As humans without an expected path to take (for the sake of being a perfect fit into the society that we’ve constructed) we pursued our curiosity, learned from experience, and sought out mentors that could help us accelerate our unique path.</p><p>We’ve got it all backward.</p><p>Since we were young, we’ve been conditioned to:</p><ul><li>Please others and be graded on performance (rather than what we truly learned)</li><li>Cater to the wants and needs of society (because accepting someone elses ideology is easier than creating our own way of living)</li><li>Limit our own minds to the point of wondering, “Is this all there is?”</li></ul><p>This is a disaster.</p><p>Go to school, do what you’re told, get a degree, be trained into a replaceable job with a set income that determines your value in society…</p><p>Question nothing, only see what’s in front of you, and don’t you dare be better than me! I say I want the best for you… but that’s just a guise to justify my unconscious actions that signal the opposite.</p><p>The new education system doesn’t rely on society.</p><p>It relies on you.</p><p>Self-education is the answer, but nobody knows how to self-educate… and that’s kinda the point.</p><h2 id="_5-steps-to-take-your-education-into-your-own-hands" tabindex="-1">5 Steps To Take Your Education Into Your Own Hands <a class="header-anchor" href="#_5-steps-to-take-your-education-into-your-own-hands" aria-label="Permalink to &quot;5 Steps To Take Your Education Into Your Own Hands&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>We haven’t entered another renaissance era.</p><p>Ideas, information, and advice are everywhere.</p><p>People are losing trust in religion, government, and forced ideology.</p><p>This leaves us in a perpetual state of anxiety and uncertainty. Order has been lost and our minds are hit with the backlash.</p><p>In the past, religious doctrine and accepted cultural standards gave us an external hierarchy of goals to pursue. It brought order to our lives. We didn’t have to <em>think</em> about what the future held. A blessing and a curse.</p><p>Now, we must take matters into our own hands. Here’s how:</p><p><strong>1) Know Thyself</strong></p><blockquote><p>If you don’t know what you want, understand what you don’t want and work in the opposite direction.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1537030087874420738?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 15, 2022</a></p></blockquote><p>What do you want in your future?</p><p>How are you going to get there? What are the goals?</p><p>Why do you want to get there? What is important to you?</p><p>Contemplate your <a href="https://youtu.be/h8BrVhksQw8" target="_blank" rel="noreferrer">vision, goals, and values</a> over the next week. Then internalize these next steps.</p><p><strong>2) Pursue Your Curiosity</strong></p><p>3 things:</p><ul><li>Potential utility</li><li>Potential creativity</li><li>Potential enjoyability</li></ul><p>Those are what you should look for when building a profitable skill stack.</p><p>Yes, <em>stack</em>. Not singular skill.</p><p>This is where most creatives go wrong. You can’t just create art all day and hope someone sees it the way you do.</p><p>If you want to pursue an artistic skill, great, do it, but you must be open to offering that skill in a way that helps others get what they want.</p><p>Writing, marketing, sales.</p><p>Learn those. That gives any other skill you choose to learn utility.</p><p>Enjoyability? That comes with the process. Try things out. Throw sh*t at a wall.</p><p><strong>3) Start A Personal Project</strong></p><blockquote><p>You can read books and listen to advice all day long, but it means nothing unless you apply and experience those teachings.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1476483719653376003?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">December 30, 2021</a></p></blockquote><p>Projects are powerful.</p><p>One, they get you out of tutorial hell, the endless cycle of learning that tricks you into thinking that you are making progress.</p><p>Two, they force you to build something that serves a function in the real world.</p><p>Keyword: <em>build</em>.</p><p>Three, they teach you how to pursue sources of good dopamine. You can make progress, get obsessed, and feel the energy that all great entrepreneurs talk about.</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">Write a newsletter</a> and uncover the holes in your writing.</p><p>Create a banner for your brand and be forced to research tools you can use to create those images.</p><p>Build out that “million dollar” app idea that you had last year. It’s not like you can’t look up “how to build an app” on YouTube, do some digging, and spend a few months actually doing it.</p><p>Don’t let your mind fool you.</p><p><strong>4) Seek Specific Knowledge</strong></p><blockquote><p>Fail, then learn.\\</p><p>Act, then ask.\\</p><p>Move, then steer.\\</p><p>A tank full of gas, directions on the map, and hands on the wheel is nothing but wishful thinking if your foot is off the pedal.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1561282467243466753?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">August 21, 2022</a></p></blockquote><p>Building a project will expose what you don’t know.</p><p>Trying to learn everything before you start will only delay this process.</p><p>When you hit a wall, find the solution.</p><p>Buy a course, watch a YouTube video, ask a specific question to someone you follow on social media, join a community, and overall… just get involved in a digital space that talks about your interests.</p><p>That’s the beautiful thing about this “new education system.”</p><p>You don’t have to pay a pretty penny to get the answers you need. Everything is out there. People just don’t know what to look up because they haven’t started a project, failed, and been given a reason to look up something specific.</p><p><em>Creators are the new professors, but teach information that the professors can’t teach until the next curriculum update</em>_._</p><p><strong>5) Take Your Project Public</strong></p><blockquote><p>“Give me a place to stand, and a lever long enough, and I will move the world.” — Archimedes</p></blockquote><p>The internet gives anyone the opportunity to build leverage.</p><ul><li>Personal websites</li><li>Writing and educating on social media</li><li>Building an audience and accepting payments</li><li>Hosting, managing, and distributing your project</li></ul><p>The coders of the world have been building solutions for years.</p><p>Most people can do whatever they want if they learn the rules, play the game, and be the “man in the arena.”</p><p>One thing I want you to know:</p><p>You will never ever ever get paid for doing what you love if you don’t have people to support you.</p><p>The internet gives you access to any and all people with a wi-fi connection (if you have a strategy and the know-how to get in front of them).</p><p>Build your project in public. Talk about your journey. Inspire others. And get the feedback necessary to make it a success.</p><p>(And remember, no feedback is still feedback. If something isn’t working, giving up isn’t the solution, clearly.)</p><p>Until next time, my friends.</p><p>— Dan Koe</p><p><strong>What Happened This Week</strong></p><p>The 2 Hour Writer is live! We had an incredible launch and 800+ students get access yesterday. Some kind words started flowing in this morning:</p><p><img src="'+o+'" alt=""></p><p><img src="'+a+'" alt=""></p><p><img src="'+n+'" alt=""></p><p>If you want to use my writing and content system, consider checking it out.</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">Enroll in the 2 Hour Writer.</a></p><p>In Modern Mastery, the personal brand master herself, <a href="https://twitter.com/sanathemonster" target="_blank" rel="noreferrer">Sana,</a> posted “How To Collaborate With Top Creators,” a key for growing on socials and meeting the people you look up to.</p><p>We also have a brand workshop scheduled for this Wednesday. We will be ripping apart profiles and teaching you how to best present yourself online.</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Readers can join MM for $5.</a></p><p>A new YouTube video about 9 steps I would take to start a writing business from scratch just went live.</p><p><a href="https://youtu.be/N8U5bzSD65Q" target="_blank" rel="noreferrer">Watch the new video here.</a></p>',113)])])}const b=r(p,[["render",h]]);export{y as __pageData,b as default};
